CREATE TABLE g_t (k TEXT, v INTEGER, w INTEGER)
SELECT COUNT(*) AS c, SUM(v) AS s, MIN(v) AS mn, MAX(v) AS mx FROM g_t
INSERT INTO g_t VALUES ('a', 1, 10), ('a', 2, NULL), ('b', NULL, 5), (NULL, 4, 7), ('b', -3, 7), (NULL, NULL, NULL)
SELECT COUNT(*) AS c, COUNT(v) AS cv, COUNT(k) AS ck, SUM(v) AS s, MIN(v) AS mn, MAX(v) AS mx FROM g_t
SELECT SUM(w) AS sw, MAX(k) AS mk, MIN(k) AS nk FROM g_t
SELECT k AS k, COUNT(*) AS c FROM g_t GROUP BY k ORDER BY k
SELECT k AS k, COUNT(*) AS c, SUM(v) AS s, MIN(w) AS mw, MAX(w) AS xw FROM g_t GROUP BY k ORDER BY k DESC
SELECT upper(k) AS uk, COUNT(*) AS c FROM g_t GROUP BY upper(k) ORDER BY uk
SELECT v + 3 AS vk, COUNT(*) AS c FROM g_t WHERE v IS NOT NULL GROUP BY v + 3 ORDER BY vk
SELECT length(k) AS lk, COUNT(*) AS c FROM g_t GROUP BY length(k) ORDER BY lk
SELECT k AS k, SUM(v) AS s FROM g_t GROUP BY k HAVING COUNT(*) > 1 ORDER BY k
SELECT k AS k, SUM(v) AS s FROM g_t GROUP BY k HAVING SUM(v) > 0 ORDER BY k
SELECT k AS k, MAX(v) AS m FROM g_t GROUP BY k HAVING MIN(v) < 0 ORDER BY k
SELECT k AS k, COUNT(*) AS c FROM g_t GROUP BY k HAVING k = 'a' ORDER BY k
SELECT k AS k, COUNT(*) AS c FROM g_t GROUP BY k HAVING k IS NULL
SELECT COUNT(*) AS c FROM g_t WHERE v > 1000
SELECT k AS k, COUNT(*) AS c FROM g_t WHERE v > 1000 GROUP BY k
SELECT SUM(v) AS s FROM g_t WHERE v > 1000
SELECT COUNT(*) AS c FROM g_t LIMIT 1
SELECT COUNT(*) AS c FROM g_t WHERE COUNT(*) > 1
SELECT k AS k, COUNT(*) AS c FROM g_t GROUP BY COUNT(*)
SELECT k AS k FROM g_t GROUP BY zz_nocol
SELECT SUM(zz_gone) AS s FROM g_t
SELECT COUNT(v) + 1 AS c1, MAX(v) * 2 AS m2 FROM g_t
SELECT k AS k, COUNT(*) AS c FROM g_t GROUP BY k ORDER BY c DESC, k LIMIT 2
SELECT MIN(k) AS mk FROM g_t WHERE k IS NOT NULL
SELECT COUNT(*) AS c, SUM(v) AS s FROM g_t WHERE k = 'b'
SELECT k AS k, COUNT(v) AS cv FROM g_t GROUP BY k HAVING COUNT(v) = 0 ORDER BY k
